  function svgOpen(w,h,label){return '<svg class="chart" viewBox="0 0 '+w+' '+h+'" width="100%" style="max-width:460px;display:block;margin:6px auto 8px;background:#fff;border:2px solid #E3E8EE;border-radius:12px;font-family:Inter,sans-serif" role="img" aria-label="'+label+'">';}
