    var o='<table class="btb" '+SLS+'><tr><th '+TH+' class="na">'+nA+'</th><th '+TH+'></th><th '+TH+' class="nb">'+nB+'</th></tr>';
    for(var st=lo;st<=hi;st++){var la=a.filter(function(v){return Math.floor(v/10)===st;}).map(function(v){return v%10;}).reverse(),
      lb=b.filter(function(v){return Math.floor(v/10)===st;}).map(function(v){return v%10;});
      o+='<tr><td class="la" style="padding:3px 10px;text-align:right;letter-spacing:1px">'+leaves(la)+'</td><td class="st" style="padding:3px 10px;text-align:center;border-left:2px solid #1B2430;border-right:2px solid #1B2430">'+st+'</td><td class="lv" style="padding:3px 10px;text-align:left;letter-spacing:1px">'+leaves(lb)+'</td></tr>';}
