  var FT=[["Goals scored",0,4,"the number of goals scored in each of N matches"],["Number of pets",0,4,"the number of pets owned by N families"],["Brothers and sisters",0,5,"how many brothers and sisters N students have"],["Shoe size",3,7,"the shoe sizes of N students"],["Times late",0,4,"how many times N students were late this term"]];
  function ftab(){var t=rnd(FT),vals=[],fs=[];for(var v=t[1];v<=t[2];v++){vals.push(v);fs.push(ri(1,9));}var N=sum(fs);return {t:t,vals:vals,fs:fs,N:N,fx:sum(vals.map(function(v,i){return v*fs[i];})),s:"The table shows "+t[3].replace("N",N)+"."};}
